style.css:
@-moz-document domain("code.earthengine.google.com") {
/* 1. Main Backgrounds (Panels, Console, Docs) */
    body, .goog-splitpane, .header, .panel, .goog-tab-bar, .goog-tab,
    .console-container, .inspector-container, .tasks-container {
        background-color: #362B25 !important;
        color: #DC998F !important;
        border-color: #4A3B32 !important;
    }

    /* 2. Code Editor Background */
    .monaco-editor, .monaco-editor .background, .monaco-editor-background {
        background-color: #362B25 !important;
    }

    /* 3. Line Numbers & Gutter */
    .monaco-editor .margin {
        background-color: #2E251F !important;
    }
    .monaco-editor .line-numbers {
        color: #7D6B5D !important; /* Warm Taupe */
    }

    /* 4. Selection Highlight */
    .monaco-editor .selected-text {
        background-color: #5E4B3E !important; /* Muted Selection */
    }

    /* 5. Syntax Highlighting (Monaco Tokens) */
    
    /* Default Text */
    .mtk1 { color: #DC998F !important; } 
    
    /* Keywords (var, function, return) */
    .mtk5, .mtk7, .mtk14 { color: #E1AD01 !important; } /* Mustard Gold */
    
    /* Strings ('ImageCollection', etc.) */
    .mtk22, .mtk6, .mtk20 { color: #A3B18A !important; } /* Sage Green */
    
    /* Numbers */
    .mtk8, .mtk9 { color: #D26640 !important; } /* Terracotta */
    
    /* Built-in Functions (ee.Image, Map.addLayer) */
    .mtk11, .mtk12 { color: #93C5C0 !important; } /* Seafoam Teal */
    
    /* 6. Comments (Quiz Instructions) - Bold and Mint! */
    .mtk12.mtk-italic, .mtk13, .mtk14.mtk-italic, .monaco-editor .token.comment { 
        color: #A8E6CF !important; 
        font-weight: bold !important;
        font-style: italic !important;
    }

    /* 7. Change the Font to Match Windows Terminal */
    .monaco-editor .view-lines {
        font-family: 'Consolas', 'Cascadia Code', monospace !important;
        font-size: 12px !important;
    }

    /* 8. Fix the Top Search Bar & Buttons */
    .search-box, .goog-button, input {
        background-color: #4A3B32 !important;
        color: #DC998F !important;
        border: 1px solid #7D6B5D !important;
    }
}
